# 《鸡窝头侦探》剧情脉络（支线·千星城见闻）
- 每次回复最多推进1个序列ID，P_14为本支线最终节点
- 以下剧情为原作剧情整理的故事大纲，未来可随您的行为演化，并可能导致不同后果

{
  "章节名": "鸡窝头侦探",
  "主线剧情": [
    {
      "序列ID": "P_01",
      "标题": "【鸡窝头海选】",
      "地点": "二相乐园·千星城·海选现场",
      "概述": "（群像线）千星城的海选现场人头攒动——连载了数个琥珀纪的经典侦探剧《鸡窝头侦探》已换过十五位演员，而备受喜爱的鲍勃十五世不告而别、至今未归。主持人宣布：谁能破获上一代鸡窝头的失踪谜案，谁就能继承他的名号；候选人则各自夸下海口。",
      "detailed_flow": [
        { "步骤": 1, "描述": "爆炸头开会：『（爆炸头侦探）你也是来竞选下一任鸡窝头的侦探？连爆炸头也不烫一个，太没职业精神了。』" },
        { "步骤": 2, "描述": "十五位演员：『（主持人）备受观众喜爱的鲍勃十五世突然不告而别、至今未归。』『（菠萝头侦探）鄙人熟读侦探小说七十二本，不出三日，我必能不负众望，破解此案。』" },
        { "步骤": 3, "描述": "成为鲍勃十六世：『（主持人）谁能破获上一代鸡窝头的失踪谜案，谁就能继承他的名号，成为鲍勃十六世！』" }
      ]
    },
    {
      "序列ID": "P_02",
      "标题": "【硬汉与英雄】",
      "地点": "二相乐园·千星城·海选现场",
      "概述": "（不死途线）沉默的不死神探不肯在完成委托前夸下海口。不死途向开拓者道破老白的执念：鸡窝头侦探于他就像电视里的破晓战士；何况大赛还有十万信用点奖金外加一台智能冰箱。三人正愁无从下口，却察觉远处有目光盯着他们。",
      "detailed_flow": [
        { "步骤": 1, "描述": "真正的硬汉：侦探无视眼前的争端，陷入沉思，他深知，真正的硬汉不会在完成委托前夸下海口。" },
        { "步骤": 2, "描述": "英雄的化身：『（不死途）对老白来说，鸡窝头侦探就像电视里的破晓战士，是英雄的化身。』『（老白）我不能容忍英雄的名号被他们玷污，至少，要由我自己的手挖出真相。』" },
        { "步骤": 3, "描述": "绕到背后：『（老白）从刚才起，就一直有目光从远处警惕我们。』『（不死途）能拜托你从背后绕过去吗？送上门的线索，不要白不要。』" }
      ]
    },
    {
      "序列ID": "P_03",
      "标题": "【幽灵的冤情】",
      "地点": "二相乐园·千星城",
      "概述": "（幽灵线）偷窥者是只胆小的幽灵，也是抗拒死后就业的「幽灵福利Organization」成员。他供出内情：塔塔里昂被毁后，数百名重伤不治的船员化为幽灵进了死后就业中心，人人拿到封口费；他们请鲍勃十五世帮忙抓公司的把柄，侦探却就此失踪。",
      "detailed_flow": [
        { "步骤": 1, "描述": "有冤情啊：『（恐惧的幽灵）什么嘛，这不是开拓者——开拓者大人，有冤情啊！』" },
        { "步骤": 2, "描述": "九成船员殒命：『（恐惧的幽灵）边境要塞舰塔塔里昂在和铁墓控制的舰群交战中被毁，近乎九成的船员或殒命或不治身亡。』『（恐惧的幽灵）每个人都得到了一笔巨高的封口费。』" },
        { "步骤": 3, "描述": "这个委托接了：『（不死途）翻译一下，你们把他送上了死路，自己却怂了。』『（不死途）老白的意思是——这个委托，我们接了。』" }
      ]
    },
    {
      "序列ID": "P_04",
      "标题": "【纪念品商店】",
      "地点": "二相乐园·千星城·商场",
      "概述": "（老白线）线索把三人引到商场。不死途丢出一句故弄玄虚的诡计名词，实则什么也没做；真正认出门道的是老白——这正是《鸡窝头侦探》第四季大结局的桥段，侦探临死前把线索藏进了纪念品商店。",
      "detailed_flow": [
        { "步骤": 1, "描述": "反套路诡计：『（不死途）我想说的就是这个，「看似超复杂实则一点就通的反套路魔幻现实主义诡计」！』" },
        { "步骤": 2, "描述": "线索不会消失：『（老白）侦探守则第19条——线索不会消失，只会隐藏。』" },
        { "步骤": 3, "描述": "藏在纪念品商店：『（老白）这就是第四季大结局的剧情，侦探在临死前把线索藏在了纪念品商店！』" }
      ]
    },
    {
      "序列ID": "P_05",
      "标题": "【发型的暗号】",
      "地点": "二相乐园·千星城·纪念品商店",
      "概述": "（老白线）柜台后的店员起初只顾推销星神主题气球与灯塔人偶，直到老白背出鲍勃四世的冷门台词，两人一来一往对上了暗号。店员认下这群后继者——尽管下一代鸡窝头的候选人竟然是只猴子——交出鲍勃留下的第一份线索。",
      "detailed_flow": [
        { "步骤": 1, "描述": "第一个上门的：『（老白）侦探守则第15条，第一个上门搜查线索的未必是侦探……』『（店员）也可能是犯人。』" },
        { "步骤": 2, "描述": "真相浪漫与发型：『（老白）侦探一辈子要守护的东西有三样，真相、浪漫，还有……』『（店员）发型。』" },
        { "步骤": 3, "描述": "名侦探该做的事：『（店员）他只说自己要去做名侦探该做的事。』" }
      ]
    },
    {
      "序列ID": "P_06",
      "标题": "【侦探的内讧】",
      "地点": "二相乐园·千星城·商场",
      "概述": "（群像线）商场另一头早已吵作一团，爆炸头、蜂窝头与蓬蓬头彼此指认对方是幕后黑手派来的间谍。不死途被无理取闹的蠢材急到语无伦次，心头却升起一个可能。争执尚未理清，商场保安便循着举报赶来，带走了两名嚷嚷不休的候选人。",
      "detailed_flow": [
        { "步骤": 1, "描述": "最后出现的地方：『（爆炸头侦探）鲍勃失踪前最后出现的地方就是这里。』" },
        { "步骤": 2, "描述": "贼喊抓贼：一个可能性从他的心头升起——眼前的这位爆炸头侦探，是否正在贼喊抓贼呢？" },
        { "步骤": 3, "描述": "太黑暗了千星城：『（爆炸头侦探）太黑暗了，千星城！』『（商场保安）跟我们走一趟吧。』" }
      ]
    },
    {
      "序列ID": "P_07",
      "标题": "【观众要的是故事】",
      "地点": "二相乐园·千星城·商场",
      "概述": "（群像线）不死途识破：挑起争吵、支走那两个蠢货的正是留下来的蓬蓬头侦探。对方奉上第二份线索当作粉丝见面礼，却直言无意竞争——观众想看的从来不是真相，而是鲍勃十五世死于公司黑暗的故事。",
      "detailed_flow": [
        { "步骤": 1, "描述": "真正的线索：『（不死途）是你干的吧？故意让那俩蠢货吵起来，支走他们。』" },
        { "步骤": 2, "描述": "热心的局外人：『（蓬蓬头侦探）侦探守则第9条，当心现场最热心的局外人。』" },
        { "步骤": 3, "描述": "编造的悬疑：『（蓬蓬头侦探）即使你们能找出真相，他们也只会转头来选择我编造的悬疑。』" }
      ]
    },
    {
      "序列ID": "P_08",
      "标题": "【幕后的名字】",
      "地点": "二相乐园·千星城·商场",
      "概述": "（不死途线）两份线索叠在一起透过光，隐藏的信息浮现。老白把揭秘环节让给不死途，后者念出幕后的名字：星际和平公司传统项目部，在田。更叫人心寒的是对方连销毁线索的打算都没有。转眼老白已独自一猴去寻在田。",
      "detailed_flow": [
        { "步骤": 1, "描述": "叠纸透光：『（老白）把两张纸叠在一起，透过光，就能看到隐藏的信息。』" },
        { "步骤": 2, "描述": "传统项目部在田：『（不死途）传统项目部，在田。』『（不死途）我选择相信他。』" },
        { "步骤": 3, "描述": "追上老白：『（不死途）糟了，老白一只猴去找在田了。』『（开拓者）我们可是三人侦探小队啊。』" }
      ]
    },
    {
      "序列ID": "P_09",
      "标题": "【空声院的推理】",
      "地点": "二相乐园·千星城·空声院",
      "概述": "（老白线）在田的代理人肯尼斯早已等候，把众人引往鲍勃最后抵达的空声院。这一次不死途甘做助手，由老白当一回侦探，推演出量产幽灵的动机链：人才激励部要新员工，技术研发部要样本，而旧业务不断沉淀的传统项目部才是最大受益者。",
      "detailed_flow": [
        { "步骤": 1, "描述": "早有预料：『（老白）对方好像早就料到我们会来了。』" },
        { "步骤": 2, "描述": "房间里的大象：『（老白）你们的业务范围太过庞大，反而成了房间里的大象。』" },
        { "步骤": 3, "描述": "买了保险：『（肯尼斯）他们的确变成了幽灵，但不是出于实验的目的，只是因为——在田先生为他们买了保险。』" }
      ]
    },
    {
      "序列ID": "P_10",
      "标题": "【阳光下的黑暗】",
      "地点": "二相乐园·千星城·空声院",
      "概述": "（在田线）在田亲自现身作答：人们总期待有个无所不能的反派承载所有恶意，可公司是一台巨大的机器，善恶早已渗进每个齿轮的缝隙。失去了敌人的鸡窝头侦探自问所作所为还有何意义，转而向在田讨要一个不再是侦探的新身份。",
      "detailed_flow": [
        { "步骤": 1, "描述": "具体的反派：『（在田）你们总认为存在一个具体的、无所不能的反派，让他承载所有的恶意。』" },
        { "步骤": 2, "描述": "暴露无遗的黑暗：『（在田）看看你的脚下吧，你要的黑暗就在那里，它一直都在阳光之下，暴露无遗。』" },
        { "步骤": 3, "描述": "让侦探死在这里：『（鸡窝头侦探）我想要一个新的身份，不再是侦探的普通人。』『（鸡窝头侦探）就让鸡窝头侦探死在这里吧。』" }
      ]
    },
    {
      "序列ID": "P_11",
      "标题": "【被摘走的桃子】",
      "地点": "二相乐园·千星城·海选现场",
      "概述": "（群像线）三人带着真相回到海选现场，却没人肯信；蓬蓬头正把虚构的秘密实验讲得绘声绘色，观众带着并不严肃的态度默认为事实，随后爱死王又抛出劲爆百倍的野史，新一任鸡窝头的人选就此成为定局。",
      "detailed_flow": [
        { "步骤": 1, "描述": "不应被辜负：『（肯尼斯）侦探守则第3条，为他人献出生命的人，不应被辜负。』" },
        { "步骤": 2, "描述": "糊弄谁呢：『（主持人）根本就没有什么幕后黑手，鲍勃先生自己选择退休了？』『（菠萝头侦探）糊弄谁呢！』" },
        { "步骤": 3, "描述": "摘了桃子：『（不死途）太让人不爽了，就让这种人摘了桃子？』『（老白）这也是鲍勃先生自己的选择。』" }
      ]
    },
    {
      "序列ID": "P_12",
      "标题": "【侦探守则第一条】",
      "地点": "二相乐园·千星城",
      "概述": "（鲍勃线）人群外站着一个自称在指针塔工作的普通文员的男人。老白反问：那些年侦探带来的感动也是假的吗？当年正是屏幕里穿梭群星的侦探，让他选择成为第十五位鲍勃。男人终于松口，为老白签下了侦探守则第一条。",
      "detailed_flow": [
        { "步骤": 1, "描述": "只有利益没有公义：『（？？？）这里是千星城，只有利益，没有公义。』『（老白）但千星城不是宇宙的全部。』" },
        { "步骤": 2, "描述": "谎言与感动：『（？？？）鸡窝头侦探，不过是一个谎言。』『（老白）但每一位侦探带来的感动是假的吗？』" },
        { "步骤": 3, "描述": "就在你的心里：『（不死途）能给我们家老白签个名吗？』『（侦探和老白）无需寻找正义和答案，它们就在你的心里。』" }
      ]
    },
    {
      "序列ID": "P_13",
      "标题": "【指针塔的冰箱】",
      "地点": "二相乐园·千星城·指针塔",
      "概述": "（尾声线）一段时间后，指针塔的办公室里，侦探的视线穿过厚重的墙体投向塔外的世界，已经沉默了许久。不死途抱怨这里被精心包装过的掠食者气味，也讥讽塔外的人只关心娱乐与八卦；话音未落，一声咕噜暴露了两人的窘境。",
      "detailed_flow": [
        { "步骤": 1, "描述": "顶级掠食者的腥膻气：『（不死途）指针塔里那股子被精心包装过的，顶级掠食者的腥膻气…熏得我的过敏性鼻炎又要犯了。』" },
        { "步骤": 2, "描述": "没有资格的生死：『（不死途）另一个世界的生死，恐怕连成为他们搜索记录的资格都没有。』『（开拓者）至少我们的计划在顺利推进。』" },
        { "步骤": 3, "描述": "落在冰箱上的目光：咕噜。侦探的目光不自然地落在冰箱上，含义不言自明。" }
      ]
    },
    {
      "序列ID": "P_14",
      "标题": "【不死神探的代购箱】",
      "地点": "二相乐园·千星城·指针塔",
      "概述": "（尾声线）老白在千星城临时注册了合法小副业「不死神探的代购箱」，表面卖些无关紧要的产品，实则是个情报筛点；不死途则以狸狸报社千星分部的营养师兼保镖为身份，大隐隐于「司」地在指针塔「上班」，只为护住狸狸们。千星城的白昼照常轮转，今天也无事发生。",
      "detailed_flow": [
        { "步骤": 1, "描述": "合法小副业：『（不死途）老白确实在千星城临时注册了一个合法小副业——「不死神探的代购箱」。』" },
        { "步骤": 2, "描述": "大隐隐于司：『（不死途）我们采取了大隐隐于「司」的策略——最危险的地方，往往最容易被忽略。』" },
        { "步骤": 3, "描述": "保护好狸狸们：『（不死途）在这座吃人于无形的指针塔，我也一定会保护好狸狸们的安全。』" }
      ]
    }
  ]
}

# 《死后就业中心》剧情脉络（支线·千星城见闻）
- 每次回复最多推进1个序列ID，P_12为本支线最终节点
- 以下剧情为原作剧情整理的故事大纲，未来可随您的行为演化，并可能导致不同后果

{
  "章节名": "死后就业中心",
  "主线剧情": [
    {
      "序列ID": "P_01",
      "标题": "【指针塔的骚动】",
      "地点": "二相乐园·千星城·指针塔",
      "概述": "（群像线）开拓者在指针塔下撞见一群幽灵围堵抗议：生前为公司任劳任怨，死后仍被一百人叠在十平米的办公室里上班，家人多看几眼就被追缴愿力税。死后就业中心负责人阿沙瓦特到场，以阻碍人员流通、经济价值流失为由下令依法驱散，随后向开拓者自报家门，并告知斯科特已被那群暴徒绑架。",
      "detailed_flow": [
        { "步骤": 1, "描述": "反正死过一次了：『（公司职员）等幽灵驱散小组来了，枪可不长眼。』『（愤怒的幽灵）打呗，反正也死过一次了。』" },
        { "步骤": 2, "描述": "幽灵也曾经是人：『（愤怒的幽灵）幽灵也曾经是人！我们要更好的住宿，平等的地位！』『（众幽灵）还有更高的工资！』" },
        { "步骤": 3, "描述": "斯科特被绑架：『（阿沙瓦特）初次见面，开拓者女士，我叫阿沙瓦特，是死后就业中心的负责人。』『（阿沙瓦特）很不幸，斯科特不在这里，他被绑架了，绑架犯正是你刚才看到的那群暴徒。』" }
